void handler(int signum) {
    // Only use async-safe functions!
    // Set a global volatile sig_atomic_t flag
    if (signum == SIGINT) { /* cleanup flag = 1 */ }
}

// Legacy function: volatile, non-portable
signal(SIGINT, handler);

// Ignore the signal
signal(SIGHUP, SIG_IGN);

// Default behavior (usually termination)
signal(SIGSEGV, SIG_DFL);
sig_atomic_t flag = 0;
// ---

struct sigaction sa;

void sa_handler(int sig, siginfo_t *info, void *ucontext) {
    // Use sa_sigaction instead of sa_handler for robust handling
}

// 1. Setup the structure
sa.sa_flags = SA_RESTART | SA_SIGINFO;
sa.sa_sigaction = sa_handler;
sigemptyset(&sa.sa_mask);
sigaddset(&sa.sa_mask, SIGTERM); // Block SIGTERM during handling

// 2. Apply the action
sigaction(SIGUSR1, &sa, NULL);
// ---

sigset_t set, oldset;

// Initialize set to block SIGQUIT
sigemptyset(&set);
sigaddset(&set, SIGQUIT);

// Temporarily block (mask) SIGQUIT
sigprocmask(SIG_BLOCK, &set, &oldset);

// Critical section...

// Restore original signal mask (unblock)
sigprocmask(SIG_SETMASK, &oldset, NULL);
